void vig_io_toxic_mire(u8 op, u8 arg, u8 *dst) BANKED {
    u8 i, n;
    switch (op) {
    case VIG_OP_META:
        memcpy(dst, toxic_mire_meta + (u16)arg * VIG_META_SIZE, VIG_META_SIZE);
        break;
    case VIG_OP_TILES:
        i = (u8)(arg << 5);
        n = (u8)(146u - i);
        if (n > 32) n = 32;
        set_bkg_data(VIG_SLOT(i), n, toxic_mire_tiles + ((u16)i << 4));
        break;
    case VIG_OP_ROWS:
        for (i = (u8)(arg * 6); i < (u8)(arg * 6 + 6); ++i) {
            set_bkg_tiles(0, i, 20, 1, toxic_mire_map + (u16)i * 20);
            VBK_REG = 1;
            set_bkg_tiles(0, i, 20, 1, toxic_mire_attr + (u16)i * 20);
            VBK_REG = 0;
        }
        break;
    case VIG_OP_TEXT:
        set_bkg_tiles(0, 15, 20, 2, toxic_mire_text_t + (u16)arg * 40);
        VBK_REG = 1;
        set_bkg_tiles(0, 15, 20, 2, toxic_mire_text_a + (u16)arg * 40);
        VBK_REG = 0;
        break;
    }
    dst;
}
